/// Cost lookup helper folding `bgForcePowerCostSaberThrow` back into the
/// `[fp index][fp level]` shape the Raven source indexes directly. See the
/// note on `bgForcePowerCost` above.
#[inline]
fn force_power_cost(fp: c_int, level: c_int) -> c_int {
    if fp as usize == FP_SABERTHROW as usize {
        bgForcePowerCostSaberThrow[level as usize]
    } else {
        bgForcePowerCost[fp as usize][level as usize]
    }
}

/// Raven `BG_FileExists`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:319-333`
pub fn BG_FileExists(fileName: *const c_char, bg: &BgState, traps: &dyn BgTraps) -> qboolean {
    if !fileName.is_null() {
        unsafe {
            if *fileName != 0 {
                let mut fh = 0;
                traps.fs_fopen(fileName, &mut fh, FS_READ);
                if fh > 0 {
                    traps.fs_fclose(fh);
                    return qtrue;
                }
            }
        }
    }
    qfalse
}

/// Raven `BG_ParseField`.
///
/// Takes a key/value pair and sets the binary values in a gentity/centity/
/// whatever the hell you want.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:358-423`
// PORT-NOTE(ctx-cascade): gained `ctx: GameContext<'_>` so the `F_PARM*` branch
// can forward to the game-tier `Q3_SetParm` (which now reaches the entity arena
// through `ctx.world`); both call sites (`G_SpawnGEntityFromSpawnVars`,
// `SP_worldspawn`) already carry `ctx`.
pub fn BG_ParseField(
    ctx: GameContext<'_>,
    l_fields: *mut BG_field_t,
    key: *const c_char,
    value: *const c_char,
    ent: *mut byte,
) {
    unsafe {
        let mut f = l_fields;
        loop {
            if (*f).name.is_null() {
                break;
            }
            if Q_stricmp((*f).name, key) == 0 {
                // found it
                let b = ent;
                match (*f).r#type {
                    fieldtype_t::F_LSTRING => {
                        // QAGAME (jampgame) branch: G_NewString.
                        let s = G_NewString(value);
                        *(b.offset((*f).ofs as isize) as *mut *mut c_char) = s;
                    }
                    fieldtype_t::F_VECTOR => {
                        // sscanf(value, "%f %f %f", &vec[0], &vec[1], &vec[2])
                        let text = std::ffi::CStr::from_ptr(value).to_string_lossy();
                        let mut nums = text.split_whitespace().filter_map(|t| t.parse::<f32>().ok());
                        let vec: vec3_t = [
                            nums.next().unwrap_or(0.0),
                            nums.next().unwrap_or(0.0),
                            nums.next().unwrap_or(0.0),
                        ];
                        let dst = b.offset((*f).ofs as isize) as *mut f32;
                        *dst = vec[0];
                        *dst.add(1) = vec[1];
                        *dst.add(2) = vec[2];
                    }
                    fieldtype_t::F_INT => {
                        let v = atoi(value);
                        *(b.offset((*f).ofs as isize) as *mut c_int) = v;
                    }
                    fieldtype_t::F_FLOAT => {
                        let v = atof(value) as f32;
                        *(b.offset((*f).ofs as isize) as *mut f32) = v;
                    }
                    fieldtype_t::F_ANGLEHACK => {
                        let v = atof(value) as f32;
                        let dst = b.offset((*f).ofs as isize) as *mut f32;
                        *dst = 0.0;
                        *dst.add(1) = v;
                        *dst.add(2) = 0.0;
                    }
                    fieldtype_t::F_PARM1
                    | fieldtype_t::F_PARM2
                    | fieldtype_t::F_PARM3
                    | fieldtype_t::F_PARM4
                    | fieldtype_t::F_PARM5
                    | fieldtype_t::F_PARM6
                    | fieldtype_t::F_PARM7
                    | fieldtype_t::F_PARM8
                    | fieldtype_t::F_PARM9
                    | fieldtype_t::F_PARM10
                    | fieldtype_t::F_PARM11
                    | fieldtype_t::F_PARM12
                    | fieldtype_t::F_PARM13
                    | fieldtype_t::F_PARM14
                    | fieldtype_t::F_PARM15
                    | fieldtype_t::F_PARM16 => {
                        // QAGAME branch: Q3_SetParm(((gentity_t*)ent)->s.number, type - F_PARM1, value).
                        let g = ent as *mut gentity_t;
                        let parm_num = (*f).r#type as c_int - fieldtype_t::F_PARM1 as c_int;
                        Q3_SetParm(ctx, (*g).s.number, parm_num, value);
                    }
                    _ => {
                        // F_IGNORE and any other tag: no-op.
                    }
                }
                return;
            }
            f = f.add(1);
        }
    }
}

/// Raven `BG_LegalizedForcePowers`.
///
/// The magical function to end all functions. This will take the force
/// power string in powerOut and parse through it, then legalize it based on
/// the supposed rank and spit it into powerOut, returning true if it was
/// legal to begin with and false if not. fpDisabled is actually only
/// expected (needed) from the server, because the ui disables force power
/// selection anyway when force powers are disabled on the server.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:439-732`
pub fn BG_LegalizedForcePowers(
    powerOut: *mut c_char,
    maxRank: c_int,
    freeSaber: qboolean,
    teamForce: c_int,
    gametype: c_int,
    fpDisabled: c_int,
) -> qboolean {
    unsafe {
        let orig = std::ffi::CStr::from_ptr(powerOut).to_string_lossy().into_owned();
        let mut maintains_validity = qtrue;

        let power_buf: String;
        if orig.len() >= 128 {
            // This should not happen. If it does, this is obviously a bogus
            // string. They can have this string. Because I said so.
            power_buf = "7-1-032330000000001333".to_string();
            maintains_validity = qfalse;
        } else {
            power_buf = orig;
        }
        let power_bytes = power_buf.as_bytes();

        // Split on '-': [0]=rank(ignored, we recompute), [1]=side, [2..]=powers digit-string.
        let mut parts = power_buf.splitn(3, '-');
        let _rank_field = parts.next().unwrap_or("");
        let side_field = parts.next().unwrap_or("");
        let powers_field = parts.next().unwrap_or("");

        let mut final_side: c_int = side_field.trim().parse::<c_int>().unwrap_or(0);
        if final_side != FORCE_LIGHTSIDE && final_side != FORCE_DARKSIDE {
            // Not a valid side. You will be dark. Because I said so.
            final_side = FORCE_DARKSIDE;
            maintains_validity = qfalse;
        }

        if teamForce != 0 && final_side != teamForce {
            // Let them join the team with their filtered powers.
            final_side = teamForce;
        }

        const NUM_FORCE_POWERS_USIZE: usize = 18;
        let mut final_powers: [c_int; NUM_FORCE_POWERS_USIZE] = [0; NUM_FORCE_POWERS_USIZE];
        for (c, ch) in powers_field.chars().take(NUM_FORCE_POWERS_USIZE).enumerate() {
            final_powers[c] = ch.to_digit(10).unwrap_or(0) as c_int;
        }

        let allowed_points = forceMasteryPoints[maxRank as usize];

        for i in 0..NUM_FORCE_POWERS_USIZE {
            if final_powers[i] != 0
                && forcePowerDarkLight[i] != 0
                && forcePowerDarkLight[i] != final_side
            {
                final_powers[i] = 0;
            }
            if final_powers[i] != 0 && (fpDisabled & (1 << i)) != 0 {
                final_powers[i] = 0;
            }
        }

        if gametype < GT_TEAM {
            final_powers[FP_TEAM_HEAL as usize] = 0;
            final_powers[FP_TEAM_FORCE as usize] = 0;
        }

        let mut used_points: c_int = 0;
        for i in 0..NUM_FORCE_POWERS_USIZE {
            let mut count_down = final_powers[i];
            while count_down > 0 {
                used_points += force_power_cost(i as c_int, count_down);
                if count_down == 1
                    && (i == FP_LEVITATION as usize
                        || (i == FP_SABER_OFFENSE as usize && freeSaber != 0)
                        || (i == FP_SABER_DEFENSE as usize && freeSaber != 0))
                {
                    used_points -= force_power_cost(i as c_int, count_down);
                }
                count_down -= 1;
            }
        }

        if used_points > allowed_points {
            let mut power_cycle: c_int = 2;
            let min_pow: c_int = if freeSaber != 0 { 1 } else { 0 };

            maintains_validity = qfalse;

            let mut attempted_cycles = 0;
            while used_points > allowed_points {
                let mut c = 0usize;
                while c < NUM_FORCE_POWERS_USIZE && used_points > allowed_points {
                    if final_powers[c] != 0 && final_powers[c] < power_cycle {
                        if c == FP_SABER_OFFENSE as usize
                            && (final_powers[FP_SABER_DEFENSE as usize] > min_pow
                                || final_powers[FP_SABERTHROW as usize] > 0)
                        {
                            let mut which_one = FP_SABERTHROW as usize;
                            if final_powers[which_one] == 0 {
                                which_one = FP_SABER_DEFENSE as usize;
                            }
                            while final_powers[which_one] > 0 && used_points > allowed_points {
                                if final_powers[which_one] > 1
                                    || ((which_one != FP_SABER_OFFENSE as usize || freeSaber == 0)
                                        && (which_one != FP_SABER_DEFENSE as usize || freeSaber == 0))
                                {
                                    used_points -=
                                        force_power_cost(which_one as c_int, final_powers[which_one]);
                                    final_powers[which_one] -= 1;
                                } else {
                                    break;
                                }
                            }
                        } else {
                            while final_powers[c] > 0 && used_points > allowed_points {
                                if final_powers[c] > 1
                                    || (c != FP_LEVITATION as usize
                                        && (c != FP_SABER_OFFENSE as usize || freeSaber == 0)
                                        && (c != FP_SABER_DEFENSE as usize || freeSaber == 0))
                                {
                                    used_points -= force_power_cost(c as c_int, final_powers[c]);
                                    final_powers[c] -= 1;
                                } else {
                                    break;
                                }
                            }
                        }
                    }
                    c += 1;
                }

                power_cycle += 1;
                attempted_cycles += 1;

                if attempted_cycles > NUM_FORCE_POWERS_USIZE as c_int {
                    // I think this should be impossible. But just in case.
                    break;
                }
            }

            if used_points > allowed_points {
                // Still? Fine then.. we will kill all of your powers, except
                // the freebies.
                for i in 0..NUM_FORCE_POWERS_USIZE {
                    final_powers[i] = 0;
                    if i == FP_LEVITATION as usize
                        || (i == FP_SABER_OFFENSE as usize && freeSaber != 0)
                        || (i == FP_SABER_DEFENSE as usize && freeSaber != 0)
                    {
                        final_powers[i] = 1;
                    }
                }
                used_points = 0;
            }
        }

        if freeSaber != 0 {
            if final_powers[FP_SABER_OFFENSE as usize] < 1 {
                final_powers[FP_SABER_OFFENSE as usize] = 1;
            }
            if final_powers[FP_SABER_DEFENSE as usize] < 1 {
                final_powers[FP_SABER_DEFENSE as usize] = 1;
            }
        }
        if final_powers[FP_LEVITATION as usize] < 1 {
            final_powers[FP_LEVITATION as usize] = 1;
        }

        for i in 0..NUM_FORCE_POWERS_USIZE {
            if final_powers[i] > FORCE_LEVEL_3 {
                final_powers[i] = FORCE_LEVEL_3;
            }
        }

        if fpDisabled != 0 {
            if fpDisabled & (1 << (FP_LEVITATION as usize)) != 0 {
                final_powers[FP_LEVITATION as usize] = 1;
            }
            if fpDisabled & (1 << (FP_SABER_OFFENSE as usize)) != 0 {
                final_powers[FP_SABER_OFFENSE as usize] = 3;
            }
            if fpDisabled & (1 << (FP_SABER_DEFENSE as usize)) != 0 {
                final_powers[FP_SABER_DEFENSE as usize] = 3;
            }
        }

        if final_powers[FP_SABER_OFFENSE as usize] < 1 {
            final_powers[FP_SABER_DEFENSE as usize] = 0;
            final_powers[FP_SABERTHROW as usize] = 0;
        }

        // We finally have all the force powers legalized and stored locally.
        // Put them all into the string and return the result: rank, side,
        // then one digit per power (`va`/`Q_strcat` resolved to owned
        // `String` building per the bless-the-rule appendix).
        let mut out = format!("{}-{}-", maxRank, final_side);
        for i in 0..NUM_FORCE_POWERS_USIZE {
            out.push(char::from_digit(final_powers[i].max(0) as u32, 10).unwrap_or('0'));
        }

        let bytes = out.as_bytes();
        std::ptr::copy_nonoverlapping(bytes.as_ptr() as *const c_char, powerOut, bytes.len());
        *powerOut.add(bytes.len()) = 0;

        maintains_validity
    }
}

/// Raven `vectoyaw`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:1773-1792`
pub fn vectoyaw(
    vec: vec3_t,
) -> f32 {
    let mut yaw: f32;

    if vec[YAW] == 0.0 && vec[PITCH] == 0.0 {
        yaw = 0.0;
    } else {
        if vec[PITCH] != 0.0 {
            yaw = vec[YAW].atan2(vec[PITCH]) * 180.0 / std::f32::consts::PI;
        } else if vec[YAW] > 0.0 {
            yaw = 90.0;
        } else {
            yaw = 270.0;
        }
        if yaw < 0.0 {
            yaw += 360.0;
        }
    }

    yaw
}

/// Raven `BG_HasYsalamiri`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:1794-1808`
pub fn BG_HasYsalamiri(
    gametype: c_int,
    ps: *mut playerState_t,
) -> qboolean {
    unsafe {
        if gametype == GT_CTY
            && ((*ps).powerups[PW_REDFLAG as usize] != 0 || (*ps).powerups[PW_BLUEFLAG as usize] != 0)
        {
            return qtrue;
        }
        if (*ps).powerups[PW_YSALAMIRI as usize] != 0 {
            return qtrue;
        }
        qfalse
    }
}

/// Raven `BG_CanUseFPNow`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:1810-1874`
pub fn BG_CanUseFPNow(
    gametype: c_int,
    ps: *mut playerState_t,
    time: c_int,
    power: forcePowers_t,
) -> qboolean {
    unsafe {
        if BG_HasYsalamiri(gametype, ps) != 0 {
            return qfalse;
        }

        if (*ps).forceRestricted != 0 || (*ps).trueNonJedi != 0 {
            return qfalse;
        }

        if (*ps).weapon == WP_EMPLACED_GUN {
            // can't use any of your powers while on an emplaced weapon
            return qfalse;
        }

        if (*ps).m_iVehicleNum != 0 {
            // can't use powers while riding a vehicle (this may change, I
            // don't know)
            return qfalse;
        }

        if (*ps).duelInProgress != 0 {
            if power as c_int != FP_SABER_OFFENSE
                && power as c_int != FP_SABER_DEFENSE
                && power as c_int != FP_LEVITATION
            {
                if (*ps).saberLockFrame == 0 || power as c_int != FP_PUSH {
                    return qfalse;
                }
            }
        }

        if (*ps).saberLockFrame != 0 || (*ps).saberLockTime > time {
            if power as c_int != FP_PUSH {
                return qfalse;
            }
        }

        if (*ps).fallingToDeath != 0 {
            return qfalse;
        }

        if ((*ps).brokenLimbs & (1 << BROKENLIMB_RARM as c_int)) != 0
            || ((*ps).brokenLimbs & (1 << BROKENLIMB_LARM as c_int)) != 0
        {
            // powers we can't use with a broken arm. (`if`/`==` chain, not a
            // `match` on unresolved bare `FP_*` names — see the note on
            // `BG_CanItemBeGrabbed`'s `IT_*` chain above.)
            let p = power as c_int;
            if p == FP_PUSH || p == FP_PULL || p == FP_GRIP || p == FP_LIGHTNING || p == FP_DRAIN {
                return qfalse;
            }
        }

        qtrue
    }
}

