/// Raven `BG_ModelCache`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:3200-3224`
pub fn BG_ModelCache(
    modelName: *const c_char,
    skinName: *const c_char,
    bg: &BgState,
    traps: &dyn BgTraps,
) -> c_int {
    // PORT-NOTE(qagame-cfg): jampgame is the `QAGAME` build, so this ports the
    // `#ifdef QAGAME` branch (the `#else` path's `trap_R_RegisterModel` has no
    // game syscall). Precache the ghoul2 model, then discard it; return 0.
    unsafe {
        let mut g2: *mut c_void = core::ptr::null_mut();

        if !skinName.is_null() && *skinName != 0 {
            traps.r_register_skin(skinName);
        }

        // I could hook up a precache ghoul2 function, but oh well, this works
        traps.g2api_init_ghoul2_model(&mut g2 as *mut *mut c_void, modelName, 0, 0, 0, 0, 0);
        if !g2.is_null() {
            // now get rid of it
            traps.g2api_clean_ghoul2_models(&mut g2 as *mut *mut c_void);
        }
        0
    }
}

/// Raven `BG_Alloc`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:3328-3341`
pub fn BG_Alloc(size: c_int, bg: &mut BgState) -> *mut c_void {
    // C masks with unsigned `0xfffffffc`; `!3` is the same i32 bit pattern.
    bg.bg_poolSize = (bg.bg_poolSize + 0x00000003) & !3;
    if bg.bg_poolSize + size > bg.bg_poolTail {
        panic!(
            "BG_Alloc: buffer exceeded tail ({} > {})",
            bg.bg_poolSize + size,
            bg.bg_poolTail
        );
    }
    bg.bg_poolSize += size;
    unsafe { bg.bg_pool.as_mut_ptr().add((bg.bg_poolSize - size) as usize) as *mut c_void }
}

/// Raven `BG_AllocUnaligned`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:3343-3354`
pub fn BG_AllocUnaligned(size: c_int, bg: &mut BgState) -> *mut c_void {
    if bg.bg_poolSize + size > bg.bg_poolTail {
        panic!(
            "BG_AllocUnaligned: buffer exceeded tail ({} > {})",
            bg.bg_poolSize + size,
            bg.bg_poolTail
        );
    }
    bg.bg_poolSize += size;
    unsafe { bg.bg_pool.as_mut_ptr().add((bg.bg_poolSize - size) as usize) as *mut c_void }
}

/// Raven `BG_TempAlloc`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:3356-3369`
pub fn BG_TempAlloc(size: c_int, bg: &mut BgState) -> *mut c_void {
    let mut sz = size;
    sz = (sz + 0x00000003) & !3;
    if bg.bg_poolTail - sz < bg.bg_poolSize {
        panic!(
            "BG_TempAlloc: buffer exceeded head ({} > {})",
            bg.bg_poolTail - sz,
            bg.bg_poolSize
        );
    }
    bg.bg_poolTail -= sz;
    unsafe { bg.bg_pool.as_mut_ptr().add(bg.bg_poolTail as usize) as *mut c_void }
}

// Raven `MAX_POOL_SIZE` — QAGAME (jampgame) arm; CGAME/ui arms are dropped
// per porting-rules §20 (MP jampgame only).
// Source: `oracle/oracle/codemp/game/bg_misc.c:3311-3316`
const MAX_POOL_SIZE: c_int = 3000000;

/// Raven `BG_TempFree`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:3371-3381`
pub fn BG_TempFree(size: c_int, bg: &mut BgState) {
    let mut sz = size;
    sz = (sz + 0x00000003) & !3;
    if bg.bg_poolTail + sz > MAX_POOL_SIZE {
        panic!(
            "BG_TempFree: tail greater than size ({} > {})",
            bg.bg_poolTail + sz,
            MAX_POOL_SIZE
        );
    }
    bg.bg_poolTail += sz;
}

/// Raven `BG_StringAlloc`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:3383-3390`
pub fn BG_StringAlloc(source: *const c_char, bg: &mut BgState) -> *mut c_char {
    unsafe {
        // Raven `strlen(source)+1` / `strcpy(dest, source)`. `dest` is sized
        // exactly `len`, so `Q_strncpyz(dest, source, len)` copies the same
        // bytes (strlen chars + NUL) as the unbounded `strcpy`.
        let len = crate::q_shared::Q_strlen(source) + 1;
        let dest = BG_Alloc(len as c_int, bg);
        Q_strncpyz(dest as *mut c_char, source, len as c_int);
        dest as *mut c_char
    }
}

/// Raven `BG_OutOfMemory`.
///
/// Source: `oracle/oracle/codemp/game/bg_misc.c:3392-3395`
pub fn BG_OutOfMemory(bg: &BgState) -> qboolean {
    if bg.bg_poolSize >= MAX_POOL_SIZE {
        qtrue
    } else {
        qfalse
    }
}
